	model.PageNew(pages, 2, 450, 1000, 0, model.PkImage())
	port.CellsPush(mask, 1)
	port.CellsPush(mask, 1)
	lawLine(fl, fw, et, 1, 600, 90)
	for i < 3 {
		lawPricedRow(fl, fw, et, 1, 700+(i*40), 65+i)
		i += 1
	}
	i = 0
	for i < 3 {
		lawPricedRow(fl, fw, et, 2, 40+(i*40), 65+i)
		i += 1
	}
	lawLine(fl, fw, et, 2, 350, 81)
